eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   SERVICE_DETAILS: () => (/* binding */ SERVICE_DETAILS)\n/* harmony export */ });\nconst SERVICE_DETAILS = {\n    \"villanyszereles-felujitas\": {\n        slug: \"villanyszereles-felujitas\",\n        h1: \"Villanyszerelés és felújítás\",\n        title: \"Villanyszerelés, felújítás, áramkör-bővítés | SIROVILL\",\n        description: \"Dugaljak, kapcsolók, világítási körök, áramkör-bővítés és elosztószekrény szerelése. Ingyenes felmérés, novemberi kezdés.\",\n        lead: \"Új dugaljak, kapcsolók, világítási körök kialakítása, meglévő hálózat felújítása, elosztószekrény bővítése — lakóingatlanban, irodában és telephelyen egyaránt.\",\n        mikor: [\n            {\n                cim: \"Ha kevés a konnektor\",\n                szoveg: \"A legtöbb 15-20 évnél régebbi ingatlant még olyan eszközparkhoz tervezték, ami azóta megsokszorozódott. Ilyenkor jönnek az elosztók, a hosszabbítók, és a terhelés egyetlen áramkörre koncentrálódik.\"\n            },\n            {\n                cim: \"Ha bővül a helyiség vagy a funkció\",\n                szoveg: \"Új iroda, átalakított padlástér, garázsból lett műhely, konyhafelújítás új nagyfogyasztókkal.\"\n            },\n            {\n                cim: \"Ha felújítás zajlik\",\n                szoveg: \"Amíg nyitva a fal, olcsóbb rendbe tenni a hálózatot, mint később visszabontani.\"\n            },\n            {\n                cim: \"Ha az elosztószekrény tele van\",\n                szoveg: \"Nincs hova új kismegszakítót tenni, vagy még régi típusú, cserélendő szerelvények vannak benne.\"\n            }\n        ],\n        mitCsinalunk: [\n            \"Dugaljak, kapcsolók, csatlakozási pontok kialakítása\",\n            \"Új áramkörök kiépítése — külön kör a nagyfogyasztóknak\",\n            \"Elosztószekrény bővítése vagy cseréje\",\n            \"Kismegszakítók, áram-védőkapcsolók cseréje\",\n            \"Elavult vezetékek cseréje, alumínium helyett réz\",\n            \"Terhelés felmérése a bővítés előtt\"\n        ],\n        amireFigyelunk: \"Bővítés előtt mindig megnézzük, mit bír a meglévő rendszer. Egy új áramkör önmagában nem sokat ér, ha a főbiztosíték vagy a betáplálás nem elég hozzá — ezt előre kell tisztázni, nem a munka közepén.\\n\\nA nagyfogyasztókat (mosogatógép, klíma, elektromos főzőlap, műhelygép) érdemes külön áramkörre tenni. Így ha egy eszköz hibásodik meg, nem az egész lakás áramtalanodik.\",\n        mitNeVarjon: \"Nem végzünk érintésvédelmi vagy szabványossági felülvizsgálatot, és nem állítunk ki ilyen jegyzőkönyvet — ez külön jogosultsághoz kötött. Mérőhely-kialakítással és fogyasztásmérő bekötésével sem foglalkozunk. Ha a munkához felülvizsgálati jegyzőkönyv szükséges, azt partnerünkkel biztosítjuk.\"\n    },\n    \"vilagitas-korszerusites\": {\n        slug: \"vilagitas-korszerusites\",\n        h1: \"Világítás korszerűsítés\",\n        title: \"LED világítás korszerűsítés irodába, üzembe, otthonra | SIROVILL\",\n        description: \"Fénycsövek és izzók cseréje LED-re, új világítási körök, mozgásérzékelős és időzített kapcsolás. Ingyenes felmérés.\",\n        lead: \"Elavult izzók és fénycsövek cseréje LED-re — alacsonyabb fogyasztás, jobb fényminőség, hosszabb élettartam. Irodában, üzletben, műhelyben és otthon egyaránt.\",\n        mikor: [\n            {\n                cim: \"Ha még fénycső világít\",\n                szoveg: \"A hagyományos fénycsövek beszerzése egyre nehezebb, a fogyasztásuk pedig többszöröse egy LED-esnek.\"\n            },\n            {\n                cim: \"Ha villog vagy zúg a világítás\",\n                szoveg: \"Ez jellemzően az előtét öregedésének jele — cserével a probléma véglegesen megszűnik.\"\n            },\n            {\n                cim: \"Ha sötét a munkaterület\",\n                szoveg: \"A rossz megvilágítás fáradtságot okoz, műhelyben és irodában pedig munkavédelmi kérdés is.\"\n            },\n            {\n                cim: \"Ha feleslegesen égve maradnak a lámpák\",\n                szoveg: \"Ritkán használt helyiségeknél (raktár, mosdó, folyosó, lépcsőház) a mozgásérzékelő pár hónap alatt megtérül.\"\n            }\n        ],\n        mitCsinalunk: [\n            \"Meglévő lámpatestek LED-esre cserélése\",\n            \"Fénycsöves armatúrák átalakítása vagy cseréje\",\n            \"Új világítási körök kialakítása\",\n            \"Mozgásérzékelős kapcsolás beépítése\",\n            \"Időzített és ütemezett kapcsolás\",\n            \"Kültéri és munkaterületi világítás\",\n            \"Vészvilágítás és menekülési útirányjelzés kiépítése\"\n        ],\n        amireFigyelunk: \"A LED-nél nem a wattszám számít, hanem a fényáram (lumen) és a színhőmérséklet. Egy irodába 4000K körüli semleges fehér való, egy nappaliba inkább 2700-3000K meleg fehér. Rossz színhőmérséklettel a technikailag tökéletes világítás is kellemetlen lesz.\\n\\nMunkaterületnél a megvilágítási szint (lux) az irányadó — ez helyiségtípusonként eltérő elvárás. A felmérésen ezt is megnézzük, nem csak azt, hány lámpa van.\"\n    },\n    \"villanyszerelesi-hibaelharitas\": {\n        slug: \"villanyszerelesi-hibaelharitas\",\n        h1: \"Villanyszerelési hibaelhárítás\",\n        title: \"Zárlatkeresés, hibaelhárítás, kioldó biztosíték | SIROVILL\",\n        description: \"Zárlat- és szakadáskeresés, hibás áramkörök javítása, folyamatosan kioldó kismegszakító okainak feltárása.\",\n        lead: \"Zárlatkeresés, hibás áramkörök javítása, szerelvények cseréje. Megkeresésre 1 munkanapon belül jelentkezünk.\",\n        mikor: [\n            {\n                cim: \"Ha folyamatosan kiold a kismegszakító vagy az életvédelmi relé\",\n                szoveg: \"Ez soha nem véletlen — mindig van oka, és addig ismétlődik, amíg meg nem találjuk.\"\n            },\n            {\n                cim: \"Ha egy helyiségben nincs áram\",\n                szoveg: \"Miközben máshol van — ez jellemzően egy megszakadt áramkör vagy hibás csatlakozási pont.\"\n            },\n            {\n                cim: \"Ha melegszik egy konnektor vagy kapcsoló\",\n                szoveg: \"Ez azonnali beavatkozást igényel — a melegedés jellemzően laza kötés vagy túlterhelés jele, és tűzveszélyes.\"\n            },\n            {\n                cim: \"Ha villog a világítás vagy égett szagot érez\",\n                szoveg: \"Mindkettő olyan jel, amit nem érdemes halogatni.\"\n            }\n        ],\n        mitCsinalunk: [\n            \"Zárlat- és szakadáskeresés műszeres méréssel\",\n            \"A kioldás okának feltárása (túlterhelés, szigetelési hiba, hibás eszköz)\",\n            \"Hibás konnektorok, kapcsolók, csatlakozási pontok cseréje\",\n            \"Laza kötések feltárása és javítása\",\n            \"Villódzó, nem működő világítás javítása\",\n            \"Elosztószekrény hibáinak javítása\"\n        ],\n        amireFigyelunk: \"A hibaelhárításnál a legfontosabb, hogy ne csak a tünetet szüntessük meg. Ha egy kismegszakító folyamatosan kiold, azt ki lehet cserélni egy nagyobbra — de akkor a védelem szűnik meg, nem a hiba. Mi mindig az okot keressük.\\n\\nMelegedő szerelvénynél ne várjon: kapcsolja le az adott áramkört, és szóljon minél előbb. Ez az egyetlen olyan hibatípus, ami valóban sürgős.\",\n        extraPanel: {\n            cim: \"Fontos\",\n            szoveg: \"A kivitelezés 2026. november 1-től indul, így jelenleg azonnali hibaelhárításra nem tudunk kiszállni. Ha sürgős esete van, hívjon — segítünk megtalálni, kihez fordulhat.\"\n        }\n    },\n    \"kabelezes-epitkezeskor\": {\n        slug: \"kabelezes-epitkezeskor\",\n        h1: \"Kábelezés építkezéskor\",\n        title: \"Villanyszerelés építkezéskor — nyomvonal, csövezés | SIROVILL\",\n        description: \"Erős- és gyengeáramú nyomvonalak kialakítása, amíg nyitva a fal. Nyomvonaltervezés szerkezetkész állapotban.\",\n        lead: \"Erős- és gyengeáramú nyomvonalak kialakítása, amíg még nyitva a fal — hogy utólag ne kelljen vésni vagy kábelcsatornát tenni a falra.\",\n        mikor: [\n            {\n                cim: \"Szerkezetkész állapot után, vakolás előtt\",\n                szoveg: \"Ez az egyetlen olyan időszak, amikor minden kábel költséghatékonyan a helyére kerülhet.\"\n            },\n            {\n                cim: \"Felújításnál, bontás után\",\n                szoveg: \"Ugyanaz a logika: amíg csupasz a fal, minden egyszerű.\"\n            },\n            {\n                cim: \"Ha még nincs eldöntve minden\",\n                szoveg: \"Nem baj — pont ezért érdemes üres védőcsövet is behúzni.\"\n            }\n        ],\n        mitCsinalunk: [\n            \"Nyomvonaltervezés az alaprajz alapján\",\n            \"Falhoronyvésés, csövezés, dobozolás\",\n            \"Erősáramú és gyengeáramú vezetékek összehangolt kiépítése\",\n            \"Alépítmény, kábeltálca kialakítása\",\n            \"Üres védőcsövek a jövőbeli bővítéshez\",\n            \"Együttműködés a hálózat- és biztonságtechnikai tervezéssel\"\n        ],\n        amireFigyelunk: \"A gyengeáramú kábelt (hálózat, kamera, riasztó) elkülönítjük az erősáramútól. Ha hosszan párhuzamosan futnak, az erősáram zavarhatja a jelet — képzaj, hibás riasztásjelzés formájában. Nem kell külön falba tenni, de távolságot kell tartani, és merőlegesen keresztezni.\\n\\nAz üres védőcső a legjobb ár-érték arányú döntés az egész építkezésen. Amíg nyitva a fal, néhány ezer forint. Utólag ugyanaz vésés, javítás, festés.\\n\\nAmit szinte mindenki lekés: a riasztó nyitásérzékelőinek kábele a nyílászárók mellé megy — ezt az ablakbeépítés előtt vagy közben kell megoldani. Ha az ablak már be van habozva és bevakolva, oda utólag csak bontással megy kábel.\",\n        egyKezbolPanel: {\n            cim: \"Egy kézből\",\n            szoveg: \"Ha egyszerre tervezi a villanyt, a hálózatot és a kamerarendszert, mindhármat mi tudjuk elvégezni — ugyanaz a nyomvonal, egy egyeztetés, egy ütemezés. A hálózatot a SIRONIC, a biztonságtechnikát a SIRO-VÉD divíziónk viszi.\",\n            linkek: [\n                {\n                    label: \"SIRONIC — hálózatépítés\",\n                    href: \"https://sironic.eu\"\n                },\n                {\n                    label: \"SIRO-VÉD — kamera és riasztó\",\n                    href: \"https://siroved.hu\"\n                }\n            ]\n        }\n    },\n    \"gyengearamu-kabelezes\": {\n        slug: \"gyengearamu-kabelezes\",\n        h1: \"Gyengeáramú kábelezés\",\n        title: \"Hálózati, kamera és riasztó kábelezés | SIROVILL\",\n        description: \"Strukturált hálózati kábelezés, kamera- és riasztórendszerek táp- és jelkábelezése, kaputelefon, beléptetés.\",\n        lead: \"Hálózati kábelezés, kamera- és riasztórendszerek táp- és jelkábelezése, kaputelefon és beléptetés kiépítése — a nyomvonaltól a szerelvényig.\",\n        mikor: [\n            {\n                cim: \"Ha új hálózatot építenek\",\n                szoveg: \"Iroda, telephely, családi ház — mindenhol, ahol vezetékes hálózat kell.\"\n            },\n            {\n                cim: \"Ha kamerarendszer készül\",\n                szoveg: \"A PoE-s kamera egyetlen kábelen kap képet és tápot — de az a kábel kell.\"\n            },\n            {\n                cim: \"Ha wifi-problémák vannak\",\n                szoveg: \"Az access point a mennyezetre való, a tér közepére — ehhez kábel kell a mennyezetbe.\"\n            },\n            {\n                cim: \"Ha kaputelefont vagy beléptetést szeretne\",\n                szoveg: \"Ezek is vezetékes rendszerek, a nyomvonalat előre kell tervezni.\"\n            }\n        ],\n        mitCsinalunk: [\n            \"Strukturált hálózati kábelezés (Cat6 / Cat6A)\",\n            \"Access point pozíciók kábelezése a mennyezetbe\",\n            \"Kamerák táp- és jelkábelezése, PoE-felkészítés\",\n            \"Riasztó érzékelők és központ kábelezése\",\n            \"Kaputelefon és beléptetőrendszer kábelezése\",\n            \"Patch panel és rack-szekrény bekötése\"\n        ],\n        amireFigyelunk: \"A falba kerülő kábelt 15-20 évig nem cseréli ki senki. Ezért Cat6 vagy Cat6A az ésszerű választás — a régebbi Cat5e ma még működik, de nem érdemes vele indulni.\\n\\nAz access point mennyezetre való, a helyiség közepe felé — nem a sarokba, nem a szekrény mögé. Egy jól elhelyezett többet ér, mint három rosszul elhelyezett.\\n\\nAz elosztószekrény (rack) ne a legmelegebb helyre kerüljön, legyen mellette saját áramkörön konnektor, és legyen hozzáférhető.\",\n        egyKezbolPanel: {\n            cim: \"Egy kézből\",\n            szoveg: \"A hálózat tervezését és üzemeltetését a SIRONIC, a kamera- és riasztórendszert a SIRO-VÉD divíziónk végzi. Ha mindkettőre szüksége van, egy csapattal egyeztet.\",\n            linkek: [\n                {\n                    label: \"SIRONIC — IT és hálózat\",\n                    href: \"https://sironic.eu\"\n                },\n                {\n                    label: \"SIRO-VÉD — biztonságtechnika\",\n                    href: \"https://siroved.hu\"\n                }\n            ]\n        }\n    },\n    \"okosotthon-vezerles\": {\n        slug: \"okosotthon-vezerles\",\n        h1: \"Okosotthon-vezérlés\",\n        title: \"Okos kapcsoló, redőnyvezérlés, világítás-ütemezés | SIROVILL\",\n        description: \"Okos fali kapcsolók, redőny- és világításvezérlés, ütemezett kapcsolás és jelenlét-szimuláció.\",\n        lead: \"Okos kapcsolók, redőny- és világításvezérlés, ütemezett kapcsolás — meglévő hálózatba illesztve vagy építkezéskor kialakítva.\",\n        mikor: [\n            {\n                cim: \"Ha távolról szeretné vezérelni\",\n                szoveg: \"Ami eddig csak a falon volt kapcsolható, az telefonról is elérhetővé válik.\"\n            },\n            {\n                cim: \"Ha üresen marad az ingatlan\",\n                szoveg: \"Az ütemezett világítás a legolcsóbb jelenlét-szimuláció.\"\n            },\n            {\n                cim: \"Ha sok a redőny\",\n                szoveg: \"Kézzel napi kétszer végigmenni rajtuk időigényes.\"\n            },\n            {\n                cim: \"Ha építkezik\",\n                szoveg: \"Ilyenkor a legegyszerűbb kiépíteni — az okos kapcsolók nagy részéhez nullavezeték kell a kapcsolódobozba, ami régebbi ingatlanoknál gyakran nincs.\"\n            }\n        ],\n        mitCsinalunk: [\n            \"Okos fali kapcsolók telepítése\",\n            \"Redőny- és árnyékolásvezérlés\",\n            \"Világítás ütemezése, jelenlét-szimuláció\",\n            \"Kapcsolódobozok előkészítése okos eszközökhöz\",\n            \"Meglévő rendszerbe illesztés\"\n        ],\n        amireFigyelunk: \"A legtöbb okos kapcsolóhoz nullavezeték kell a kapcsolódobozban. Régebbi ingatlanoknál ez sokszor hiányzik — ilyenkor vagy kábelezni kell, vagy olyan eszközt választani, ami nullavezeték nélkül is működik. Ez a felmérésen derül ki, nem a telepítés napján.\\n\\nÉpítkezéskor ez a probléma fel sem merül, ha előre szólnak: minden kapcsolódobozba behúzzuk a nullát, akkor is, ha most még hagyományos kapcsoló kerül bele.\"\n    },\n    \"ipari-villanyszereles\": {\n        slug: \"ipari-villanyszereles\",\n        h1: \"Ipari villanyszerelés\",\n        title: \"Gépbekötés, műhely villanyszerelés, ipari világítás | SIROVILL\",\n        description: \"Gépek villamos bekötése gyártói utasítás szerint, műhely- és üzemi villanyszerelés, ipari világítás.\",\n        lead: \"Gépek villamos bekötése a gyártói utasítás szerint, műhelyek és üzemek villanyszerelése, ipari világítás kialakítása.\",\n        mikor: [\n            {\n                cim: \"Ha új gép érkezik\",\n                szoveg: \"És be kell kötni a meglévő rendszerbe, a gyártói előírás szerint.\"\n            },\n            {\n                cim: \"Ha műhelyt vagy üzemet alakít ki\",\n                szoveg: \"Más terhelés, más igénybevétel, mint egy irodában.\"\n            },\n            {\n                cim: \"Ha bővül a termelés\",\n                szoveg: \"És a meglévő rendszer már nem bírja a megnövekedett terhelést.\"\n            },\n            {\n                cim: \"Ha korszerűsíti a csarnokvilágítást\",\n                szoveg: \"A régi típusú csarnoklámpák fogyasztása és fényminősége messze elmarad a mai LED-es megoldásoktól.\"\n            }\n        ],\n        mitCsinalunk: [\n            \"Gépek villamos bekötése gyártói dokumentáció alapján\",\n            \"Ipari csatlakozók telepítése\",\n            \"Külön áramkörök nagyfogyasztóknak\",\n            \"Ipari elosztószekrény szerelése\",\n            \"Csarnok- és munkaterületi világítás\",\n            \"Kábeltálca, védőcső, ipari nyomvonal kialakítása\"\n        ],\n        amireFigyelunk: \"Gépbekötésnél mindig a gyártói dokumentáció az irányadó — az abban előírt védelem, keresztmetszet és csatlakozás szerint dolgozunk. Ha a dokumentáció nem elérhető, azt a munka előtt tisztázni kell.\\n\\nIpari környezetben a mechanikai védelem ugyanolyan fontos, mint a villamos: ahol targonca jár, ott nem elég a falra szerelt vezeték.\",\n        mitNeVarjon: \"Nem végzünk gépkönyvi felülvizsgálatot, érintésvédelmi mérést, és nem állítunk ki jegyzőkönyvet. Ha a gép üzembe helyezéséhez ez szükséges, partnerünkkel biztosítjuk.\"\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/serviceDetails.ts\n");

